import { useEffect, useMemo, useRef, useState } from "react";
import AMapLoader from "@amap/amap-jsapi-loader";
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { fetchAnalysis, fetchDataRange, fetchDirectionRoutes, fetchPrediction, fetchPredictionCompare, fetchPredictionMeta, fetchPredictionOptions, fetchPublicConfig, fetchTraffic } from "./api/client";
import { INTERVAL_OPTIONS, PIE_COLORS, RISK_COLORS, addMinutes, axisDomain, buildDirectionPie, buildHistorySeries, buildMonitorRows, buildPredictionStats, buildSiteStats, formatRange, formatShortTime, mergePredictionSeries, resolveInterval, riskLabel, toApiTime, toInputTime } from "./adminHelpers";
import { buildEffectSeries, buildInterventions, buildRiskReasons, congestionAfter, congestionIndex, weatherSummary } from "./adminModel";
import "./App.css";

const MAP_DEFAULT = { center: [106.506145, 29.639573], zoom: 16.7 };

function App() {
  const [amapKey, setAmapKey] = useState(""); const [intersections, setIntersections] = useState([]); const [routes, setRoutes] = useState([]);
  const [predictionOptions, setPredictionOptions] = useState([]); const [predictionMeta, setPredictionMeta] = useState(null);
  const [timeLimit, setTimeLimit] = useState({ min: "", max: "" }); const [startInput, setStartInput] = useState(""); const [endInput, setEndInput] = useState(""); const [appliedRange, setAppliedRange] = useState({ start: "", end: "" }); const [timeOpen, setTimeOpen] = useState(false);
  const [siteDirections, setSiteDirections] = useState({}); const [selectedSite, setSelectedSite] = useState(""); const [trafficRows, setTrafficRows] = useState([]); const [predictionRows, setPredictionRows] = useState([]); const [predictionCompare, setPredictionCompare] = useState(null);
  const [popupOpen, setPopupOpen] = useState(false); const [popupIntervalMode, setPopupIntervalMode] = useState("auto"); const [popupAnalysis, setPopupAnalysis] = useState([]);
  const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const [refreshTick, setRefreshTick] = useState(0); const [executedActions, setExecutedActions] = useState({}); const [actionLogs, setActionLogs] = useState([]);
  const mapContainerRef = useRef(null); const mapRef = useRef(null); const AMapRef = useRef(null); const overlaysRef = useRef([]);

  useEffect(() => { (async () => { setLoading(true); try { const [config, range, routeData, options, meta] = await Promise.all([fetchPublicConfig(), fetchDataRange(), fetchDirectionRoutes(), fetchPredictionOptions(), fetchPredictionMeta()]); const min = toInputTime(range.min_timestamp); const max = toInputTime(range.max_timestamp); const start = addMinutes(max, -60); const directionMap = {}; (options || []).forEach((item) => { directionMap[item.site_name] = item.directions?.[0] || ""; }); setAmapKey(config.amap_api_key || ""); setIntersections(config.intersections || []); setRoutes(routeData || []); setPredictionOptions(options || []); setPredictionMeta(meta); setTimeLimit({ min, max }); setStartInput(start); setEndInput(max); setAppliedRange({ start, end: max }); setSiteDirections(directionMap); setSelectedSite(options?.[0]?.site_name || config.intersections?.[0]?.site_name || ""); } catch (e) { setError(`初始化失败：${e.message}`); } finally { setLoading(false); } })(); }, []);

  const selectedDirection = useMemo(() => siteDirections[selectedSite] || "", [siteDirections, selectedSite]);

  useEffect(() => { if (!appliedRange.start || !appliedRange.end || !selectedSite || !selectedDirection) return; (async () => { setLoading(true); try { const [trafficData, predictionData, compareData] = await Promise.all([fetchTraffic({ start_time: toApiTime(appliedRange.start), end_time: toApiTime(appliedRange.end), limit: 5000 }), fetchPrediction({ time_range: toApiTime(appliedRange.end), road_name: selectedSite, direction: selectedDirection }), fetchPredictionCompare({ time_range: toApiTime(appliedRange.end), road_name: selectedSite, direction: selectedDirection })]); setTrafficRows(trafficData || []); setPredictionRows(predictionData || []); setPredictionCompare(compareData); } catch (e) { setError(`主数据加载失败：${e.message}`); } finally { setLoading(false); } })(); }, [appliedRange, selectedSite, selectedDirection, refreshTick]);

  useEffect(() => { if (!popupOpen || !selectedSite || !selectedDirection || !appliedRange.start || !appliedRange.end) return; (async () => { try { setPopupAnalysis(await fetchAnalysis({ start_time: toApiTime(appliedRange.start), end_time: toApiTime(appliedRange.end), interval_minutes: resolveInterval(popupIntervalMode, appliedRange.start, appliedRange.end), road_name: selectedSite, direction: selectedDirection })); } catch { setPopupAnalysis([]); } })(); }, [popupOpen, popupIntervalMode, appliedRange, selectedSite, selectedDirection]);

  const siteStats = useMemo(() => buildSiteStats(trafficRows, predictionOptions, siteDirections).slice(0, 4), [trafficRows, predictionOptions, siteDirections]);
  const selectedSummary = useMemo(() => siteStats.find((item) => item.siteName === selectedSite) || siteStats[0], [siteStats, selectedSite]);
  const monitorRows = useMemo(() => buildMonitorRows(trafficRows), [trafficRows]);
  const predictionStats = useMemo(() => buildPredictionStats(predictionRows), [predictionRows]);
  const predictionChartData = useMemo(() => mergePredictionSeries(buildHistorySeries(trafficRows, selectedSite, selectedDirection, appliedRange.end), predictionRows), [trafficRows, selectedSite, selectedDirection, appliedRange.end, predictionRows]);
  const interventions = useMemo(() => buildInterventions(selectedSummary, predictionStats), [selectedSummary, predictionStats]);
  const effectSeries = useMemo(() => buildEffectSeries(predictionRows, interventions).map((item) => ({ ...item, label: formatShortTime(item.label) })), [predictionRows, interventions]);
  const reasons = useMemo(() => buildRiskReasons(selectedSummary, predictionStats), [selectedSummary, predictionStats]);
  const directionPieData = useMemo(() => buildDirectionPie(trafficRows, selectedSite), [trafficRows, selectedSite]);
  const popupVehicleDomain = useMemo(() => axisDomain((popupAnalysis || []).map((item) => Number(item.vehicle_count) || 0)), [popupAnalysis]);
  const popupSpeedDomain = useMemo(() => axisDomain((popupAnalysis || []).map((item) => Number(item.avg_speed) || 0)), [popupAnalysis]);
  const weather = useMemo(() => weatherSummary(trafficRows, selectedSite, selectedDirection), [trafficRows, selectedSite, selectedDirection]);
  const congestionBefore = useMemo(() => congestionIndex(selectedSummary?.avgVehicle || 0, selectedSummary?.avgSpeed || 40), [selectedSummary]);
  const congestionAfterValue = useMemo(() => congestionAfter(effectSeries, congestionBefore), [effectSeries, congestionBefore]);

  useEffect(() => { if (!mapContainerRef.current || !intersections.length || !amapKey) return; let canceled = false; (async () => { if (mapRef.current) return; try { const AMap = await AMapLoader.load({ key: amapKey, version: "2.0", plugins: ["AMap.Scale"] }); if (canceled) return; AMapRef.current = AMap; const center = intersections.length ? [intersections.reduce((s, x) => s + x.longitude, 0) / intersections.length, intersections.reduce((s, x) => s + x.latitude, 0) / intersections.length] : MAP_DEFAULT.center; const map = new AMap.Map(mapContainerRef.current, { center, zoom: MAP_DEFAULT.zoom, mapStyle: "amap://styles/darkblue", viewMode: "2D" }); map.addControl(new AMap.Scale()); mapRef.current = map; } catch (e) { setError(`地图加载失败：${e.message}`); } })(); return () => { canceled = true; }; }, [amapKey, intersections]);

  useEffect(() => { if (!mapRef.current || !AMapRef.current) return; overlaysRef.current.forEach((item) => item.setMap(null)); overlaysRef.current = []; const AMap = AMapRef.current; const riskMap = new Map(siteStats.map((item) => [item.siteName, item.risk])); intersections.forEach((site) => { const risk = riskMap.get(site.site_name) || "low"; const marker = new AMap.Marker({ position: [site.longitude, site.latitude], offset: new AMap.Pixel(-16, -16), content: `<div class="map-node ${selectedSite === site.site_name ? "active" : ""}"><span class="map-node__ring" style="border-color:${RISK_COLORS[risk]}"></span><span class="map-node__core" style="background:${RISK_COLORS[risk]}"></span></div>` }); marker.on("click", () => { setSelectedSite(site.site_name); setPopupOpen(true); }); marker.setMap(mapRef.current); overlaysRef.current.push(marker); }); routes.forEach((route) => { const risk = riskMap.get(route.site_name) || "low"; const highlighted = route.site_name === selectedSite && route.direction === selectedDirection; const polyline = new AMap.Polyline({ path: route.path.map((point) => [point.longitude, point.latitude]), strokeColor: highlighted ? "#73e7ff" : RISK_COLORS[risk], strokeWeight: highlighted ? 6 : 4, strokeOpacity: highlighted ? 0.96 : 0.55, lineCap: "round" }); polyline.setMap(mapRef.current); overlaysRef.current.push(polyline); }); }, [intersections, routes, siteStats, selectedSite, selectedDirection]);

  function confirmRange() { if (!startInput || !endInput) return; if (new Date(endInput) - new Date(startInput) < 3600000) return; setAppliedRange({ start: startInput, end: endInput }); setTimeOpen(false); }
  function runAction(action) { setExecutedActions((prev) => ({ ...prev, [action.id]: "执行中" })); setActionLogs((prev) => [{ id: `${action.id}-${Date.now()}`, time: formatShortTime(new Date()), status: "执行中", text: `${action.title} / ${action.target}` }, ...prev].slice(0, 6)); window.setTimeout(() => { setExecutedActions((prev) => ({ ...prev, [action.id]: "已下发" })); setActionLogs((prev) => [{ id: `${action.id}-done-${Date.now()}`, time: formatShortTime(new Date()), status: "已下发", text: `${action.title} / ${action.target}` }, ...prev].slice(0, 6)); }, 800); }

  return (
    <div className="admin-shell">
      <header className="top-header"><div className="brand"><div className="brand__icon" /><div><div className="brand__eyebrow">TRAFFIC INTERVENTION</div><h1>智能交通干预系统</h1></div></div><div className="header-range">{formatRange(appliedRange.start, appliedRange.end)}</div></header>
      <section className="top-control-row"><div className="road-cards">{siteStats.map((item) => <div key={item.siteName} className={`road-card ${selectedSite === item.siteName ? "active" : ""}`} onClick={() => setSelectedSite(item.siteName)} role="button" tabIndex={0}><div className="road-card__top"><span>{item.siteName}</span><select value={item.direction} onChange={(e) => setSiteDirections((prev) => ({ ...prev, [item.siteName]: e.target.value }))} onClick={(e) => e.stopPropagation()}>{item.directions.map((direction) => <option key={direction} value={direction}>{direction}</option>)}</select></div><div className="road-card__value">{item.avgVehicle || 0}</div><div className="road-card__meta"><span>平均车辆</span><i style={{ backgroundColor: RISK_COLORS[item.risk] }} /></div></div>)}</div><div className="time-wrap"><button type="button" className="time-trigger" onClick={() => setTimeOpen((v) => !v)}><span>时间选择</span><strong>{formatRange(appliedRange.start, appliedRange.end)}</strong></button>{timeOpen ? <div className="time-panel"><label><span>起始时间</span><input type="datetime-local" min={timeLimit.min} max={timeLimit.max} value={startInput} onChange={(e) => { const next = e.target.value; setStartInput(next); if (new Date(endInput) - new Date(next) < 3600000) setEndInput(addMinutes(next, 60)); }} /></label><label><span>终止时间</span><input type="datetime-local" min={startInput ? addMinutes(startInput, 60) : timeLimit.min} max={timeLimit.max} value={endInput} onChange={(e) => setEndInput(e.target.value)} /></label><button type="button" className="time-apply" onClick={confirmRange}>应用时间段</button></div> : null}</div></section>
      <section className="main-grid">
        <aside className="side-panel"><div className="panel-frame"><div className="panel-head"><h2>干预建议</h2><span>{selectedSummary?.siteName || "未选中路口"}</span></div><div className="intervention-list">{interventions.map((item) => <article key={item.id} className="action-card"><div className="action-card__title"><strong>{item.title}</strong><b>{item.priority}</b></div><span>{item.target}</span><p>{item.reason}</p><div className="action-card__foot"><small>{item.effectText}</small><button type="button" onClick={() => runAction(item)}>{executedActions[item.id] || "执行"}</button></div></article>)}</div></div><div className="panel-frame"><div className="panel-head"><h2>执行状态</h2><span>最近 6 条</span></div><div className="log-list">{actionLogs.length ? actionLogs.map((item) => <article key={item.id} className="log-card"><div><span>{item.time}</span><strong>{item.status}</strong></div><p>{item.text}</p></article>) : <div className="empty-card">暂无执行日志</div>}</div></div></aside>
        <section className="center-column"><div className="map-frame"><div className="map-frame__head"><div><span className="frame-label">主战区地图</span><strong>{selectedSummary?.siteName || "请选择路口"}</strong></div><button type="button" className="refresh-inline" onClick={() => setRefreshTick((v) => v + 1)}>刷新态势</button></div><div ref={mapContainerRef} className="map-canvas" />{selectedSummary ? <div className="map-highlight"><span>{selectedSummary.siteName}</span><strong>{selectedSummary.avgVehicle || 0}</strong><small>{selectedSummary.direction} · {riskLabel(selectedSummary.risk)}</small></div> : null}{popupOpen ? <div className="detail-popup"><div className="detail-popup__head"><div><span>{selectedSite}</span><strong>{selectedDirection}</strong></div><button type="button" onClick={() => setPopupOpen(false)}>关闭</button></div><div className="detail-popup__metrics"><div><span>平均车流量</span><strong>{selectedSummary?.avgVehicle || 0}</strong></div><div><span>平均车速</span><strong>{selectedSummary?.avgSpeed || 0} km/h</strong></div></div><label className="popup-control"><span>时间颗粒度</span><select value={popupIntervalMode} onChange={(e) => setPopupIntervalMode(e.target.value)}>{INTERVAL_OPTIONS.map((item) => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label><div className="detail-charts"><div className="mini-chart"><span>车流量</span><ResponsiveContainer width="100%" height={136}><BarChart data={popupAnalysis}><CartesianGrid stroke="rgba(148,163,184,0.14)" vertical={false} /><XAxis dataKey="bucket_start" tickFormatter={formatShortTime} tick={{ fill: "#8da6bb", fontSize: 10 }} /><YAxis tick={{ fill: "#8da6bb", fontSize: 10 }} domain={popupVehicleDomain} /><Tooltip labelFormatter={(value) => formatShortTime(value)} /><Bar dataKey="vehicle_count" fill="#5ecdfc" radius={[4, 4, 0, 0]} /></BarChart></ResponsiveContainer></div><div className="mini-chart"><span>车速</span><ResponsiveContainer width="100%" height={136}><LineChart data={popupAnalysis}><CartesianGrid stroke="rgba(148,163,184,0.14)" vertical={false} /><XAxis dataKey="bucket_start" tickFormatter={formatShortTime} tick={{ fill: "#8da6bb", fontSize: 10 }} /><YAxis tick={{ fill: "#8da6bb", fontSize: 10 }} domain={popupSpeedDomain} /><Tooltip labelFormatter={(value) => formatShortTime(value)} /><Line type="monotone" dataKey="avg_speed" stroke="#7bf4cf" strokeWidth={2.2} dot={false} /></LineChart></ResponsiveContainer></div></div><div className="wheel-block"><span>方向车流分布</span><div className="wheel-layout"><ResponsiveContainer width="46%" height={132}><PieChart><Pie data={directionPieData} dataKey="value" nameKey="name" innerRadius={26} outerRadius={50}>{directionPieData.map((item, index) => <Cell key={item.name} fill={PIE_COLORS[index % PIE_COLORS.length]} />)}</Pie><Tooltip /></PieChart></ResponsiveContainer><div className="wheel-legend">{directionPieData.map((item, index) => <div key={item.name}><i style={{ backgroundColor: PIE_COLORS[index % PIE_COLORS.length] }} /><span>{item.name}</span><strong>{item.value}</strong></div>)}</div></div></div></div> : null}</div><div className="effect-frame"><div className="panel-head"><h2>干预结果预测</h2><span>地图下方附属预测区</span></div><div className="effect-summary"><article><span>执行策略数</span><strong>{Object.keys(executedActions).length}</strong></article><article><span>拥堵指数前</span><strong>{congestionBefore}</strong></article><article><span>拥堵指数后</span><strong>{congestionAfterValue}</strong></article></div><ResponsiveContainer width="100%" height={150}><LineChart data={effectSeries}><CartesianGrid stroke="rgba(148,163,184,0.14)" vertical={false} /><XAxis dataKey="label" tick={{ fill: "#8da6bb", fontSize: 10 }} /><YAxis tick={{ fill: "#8da6bb", fontSize: 10 }} /><Tooltip /><Line type="monotone" dataKey="before" stroke="#ff7d7d" strokeWidth={2} dot={false} /><Line type="monotone" dataKey="after" stroke="#6ef2c2" strokeWidth={2} dot={false} /></LineChart></ResponsiveContainer></div></section>
        <aside className="side-panel"><div className="panel-frame"><div className="panel-head"><h2>预测预警</h2><span>{selectedSite || "未选中路口"}</span></div><div className="prediction-plot"><ResponsiveContainer width="100%" height={220}><AreaChart data={predictionChartData}><defs><linearGradient id="predictionFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#5ecdfc" stopOpacity={0.35} /><stop offset="100%" stopColor="#5ecdfc" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="rgba(148,163,184,0.14)" vertical={false} /><XAxis dataKey="label" tick={{ fill: "#8da6bb", fontSize: 10 }} /><YAxis tick={{ fill: "#8da6bb", fontSize: 10 }} /><Tooltip /><Line type="monotone" dataKey="history" stroke="#4f8cf7" strokeWidth={2} dot={false} /><Area type="monotone" dataKey="predicted" stroke="#8f9dff" fill="url(#predictionFill)" strokeWidth={2.3} /></AreaChart></ResponsiveContainer></div><div className="prediction-grid"><div><span>峰值</span><strong>{predictionStats.peak}</strong></div><div><span>低值</span><strong>{predictionStats.low}</strong></div><div><span>平均值</span><strong>{predictionStats.avg}</strong></div><div><span>天气</span><strong>{weather}</strong></div><div><span>误差百分比</span><strong>{predictionCompare?.mape ? `${predictionCompare.mape}%` : "--"}</strong></div><div><span>误差 MAE</span><strong>{predictionCompare?.mae ?? "--"}</strong></div></div><div className="reason-list">{reasons.map((item) => <div key={item} className="reason-tag">{item}</div>)}</div><div className="model-card"><span>模型信息</span><strong>{predictionMeta?.model_type || "unavailable"}</strong><p>当前预测基于历史交通流、速度、天气与时序特征生成未来一小时车流结果，默认按 10 分钟粒度展示。</p><small>测试集 MAE：{predictionMeta?.test_mae ?? "--"} · RMSE：{predictionMeta?.test_rmse ?? "--"}</small></div></div><div className="panel-frame"><div className="panel-head"><h2>重点监测</h2><span>当前时间段</span></div><div className="monitor-mini-list">{monitorRows.slice(0, 5).map((item) => <button key={`${item.siteName}-${item.direction}`} type="button" className="mini-monitor" onClick={() => { setSelectedSite(item.siteName); setSiteDirections((prev) => ({ ...prev, [item.siteName]: item.direction })); }}><div><strong>{item.siteName}</strong><span>{item.direction}</span></div><div><em style={{ color: RISK_COLORS[item.risk] }}>{riskLabel(item.risk)}</em><span>{item.avgVehicle}</span></div></button>)}</div></div></aside>
      </section>
      {error ? <div className="status-toast status-toast--error">{error}</div> : null}
      {!error && loading ? <div className="status-toast">数据同步中...</div> : null}
    </div>
  );
}

export default App;
